begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api,cuevo_worker;set local search_path=extensions,pg_catalog;select no_plan();
-- Keep the rollback fixture independent of persisted browser challenge periods.
insert into app.classes(school_id,id,academic_year_id,year_group_id,name)values('10000000-0000-4000-8000-000000000001','95120000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','42000000-0000-4000-8000-000000000001','Recognition SQL fixture');
insert into app.enrollments(school_id,class_id,student_actor_id,effective_from)values('10000000-0000-4000-8000-000000000001','95120000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','2026-09-01');
insert into app.teacher_assignments(school_id,class_id,subject_id,teacher_actor_id,effective_from)values('10000000-0000-4000-8000-000000000001','95120000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','2026-09-01');
insert into app.entitlements(school_id,code,enabled,effective_from)values('10000000-0000-4000-8000-000000000001','portfolio',true,'2026-09-01')on conflict(school_id,code)do update set enabled=true;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000001','95120000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Portfolio source','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)values('10000000-0000-4000-8000-000000000001','95010000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Selected work','Synthetic',10,'61000000-0000-4000-8000-000000000001');
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','95020000-0000-4000-8000-000000000001','95010000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','Original work');
create temporary table portfolio_test_ids(result_id uuid,evidence_id uuid,item_id uuid,policy_id uuid,period_id uuid);grant select,insert,update on portfolio_test_ids to cuevo_api;
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
insert into portfolio_test_ids(result_id)select internal.release_marking(internal.mark_submission('95020000-0000-4000-8000-000000000001',0,'Released selected work',1,0,true),1,true);
reset role;update portfolio_test_ids set evidence_id=(select evidence_id from app.result_revisions where id=result_id);
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
update portfolio_test_ids set item_id=(internal.portfolio_command('create',null,jsonb_build_object('sourceModel','numeric','evidenceId',evidence_id,'title','Selected explanation','reflection','First reflection'),'portfolio-create-golden',repeat('a',64),'portfolio-test')->>'id')::uuid;
select is((select item->>'reflection'from jsonb_array_elements(internal.read_portfolio_page(100,null,null,null)->'items')item where item->>'id'=(select item_id::text from portfolio_test_ids)),'First reflection','student selects actual released evidence and reflection');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.portfolio_command('review',(select item_id from portfolio_test_ids),'{"expectedRevision":1,"feedback":"Teacher comment","featured":true,"parentVisible":true,"confirmParentApproval":true,"confirmSourceReview":true}','portfolio-review-golden',repeat('b',64),'portfolio-test');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is((select item->>'reflection'from jsonb_array_elements(internal.read_portfolio_page(100,null,null,null)->'items')item where item->>'id'=(select item_id::text from portfolio_test_ids)),'First reflection','parent sees only exact human-approved item revision');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select internal.portfolio_command('reflection',(select item_id from portfolio_test_ids),'{"expectedRevision":1,"title":"New reflection","reflection":"Unapproved edit"}','portfolio-edit-golden',repeat('c',64),'portfolio-test');
select lives_ok($$select internal.portfolio_command('reflection',(select item_id from portfolio_test_ids),'{"expectedRevision":2,"title":"Third reflection","reflection":"Long key source"}',repeat('x',200),repeat('c',64),'portfolio-test')$$,'valid 200-character key has bounded portfolio event identity');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select lives_ok($$select internal.portfolio_command('review',(select item_id from portfolio_test_ids),'{"expectedRevision":3,"feedback":"Third reflection reviewed","featured":false,"parentVisible":false,"confirmParentApproval":false,"confirmSourceReview":true}','same-review-revoke-key',repeat('b',64),'portfolio-test')$$,'review uses its command-scoped event identity');
select lives_ok($$select internal.portfolio_command('revoke',(select item_id from portfolio_test_ids),'{"reason":"School closed parent projection"}','same-review-revoke-key',repeat('c',64),'portfolio-test')$$,'same key across separate commands cannot collide in outbox');
reset role;update app.portfolio_current set parent_revision_id=(select id from app.portfolio_revisions where item_id=(select item_id from portfolio_test_ids)and revision=1)where item_id=(select item_id from portfolio_test_ids);set local role cuevo_api;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is((select item->>'reflection'from jsonb_array_elements(internal.read_portfolio_page(100,null,null,null)->'items')item where item->>'id'=(select item_id::text from portfolio_test_ids)),'First reflection','editing creates unapproved revision without updating parent bytes');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000013',true);
select ok(not exists(select 1 from jsonb_array_elements(internal.read_portfolio_page(100,null,null,null)->'items')item where item->>'id'=(select item_id::text from portfolio_test_ids)),'peer cannot read selected work');
reset role;
select throws_ok($$update app.portfolio_revisions set reflection='Overwrite'where item_id=(select item_id from portfolio_test_ids)$$,'55000',null,'reflection revision immutable');
insert into app.school_policy_versions(school_id,version,recognition_enabled,leaderboard_enabled,reason,approved_by)select'10000000-0000-4000-8000-000000000001',coalesce(max(version),0)+1,true,true,'Synthetic recognition approval','20000000-0000-4000-8000-000000000001'from app.school_policy_versions where school_id='10000000-0000-4000-8000-000000000001';
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
update portfolio_test_ids set policy_id=(internal.development_command('policy',jsonb_build_object('expectedVersion',coalesce((select max((item->>'version')::integer)from jsonb_array_elements(internal.development_read('policies','{"limit":100}')->'items')item),0),'points',jsonb_build_object('practice',5,'revision',5,'reflection',3),'milestones','[{"key":"first-five","title":"Recorded practice","minimumPoints":5}]'::jsonb,'confirmApproval',true),'recognition-policy-golden',repeat('d',64),'recognition-test')->>'id')::uuid;
update portfolio_test_ids set period_id=(internal.development_command('period',jsonb_build_object('classId','95120000-0000-4000-8000-000000000001','policyId',policy_id,'title','Synthetic challenge','startsAt',clock_timestamp()-interval'1 hour','endsAt',clock_timestamp()+interval'1 hour','confirmApproval',true),'recognition-period-golden',repeat('e',64),'recognition-test')->>'id')::uuid;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select lives_ok($$select internal.development_command('participation',jsonb_build_object('periodId',(select period_id from portfolio_test_ids),'optIn',true,'alias','Moon 12'),'recognition-optin-golden',repeat('f',64),'recognition-test')$$,'student explicitly joins class-period with private alias');
select lives_ok($$select internal.development_command('participation',jsonb_build_object('periodId',(select period_id from portfolio_test_ids),'optIn',false,'alias',''),repeat('x',200),repeat('f',64),'recognition-test')$$,'valid 200-character key has bounded development event identity');
select internal.development_command('participation',jsonb_build_object('periodId',(select period_id from portfolio_test_ids),'optIn',true,'alias','Moon 12'),'recognition-reoptin-golden',repeat('f',64),'recognition-test');
select is(internal.development_read('summary',jsonb_build_object('limit',25,'periodId',(select period_id from portfolio_test_ids)))->>'totalPoints','0','no observed action earns invented XP');
select throws_ok('select internal.award_recognition_observation(null,null,null)','42501',null,'browser role cannot call raw award helper');
select ok(not(internal.development_read('leaderboard',jsonb_build_object('periodId',(select period_id from portfolio_test_ids),'limit',25))::text like'%learnerId%'),'leaderboard exposes alias and points without child profile identifiers');
reset role;
insert into app.units(school_id,id,course_id,title,sequence)values('10000000-0000-4000-8000-000000000001','95030000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000001','Observed practice',1);
insert into app.lessons(school_id,id,unit_id,title,sequence,body)values('10000000-0000-4000-8000-000000000001','95040000-0000-4000-8000-000000000001','95030000-0000-4000-8000-000000000001','School practice',1,'Synthetic');
insert into app.activities(school_id,id,lesson_id,title,kind,instructions,sequence)values('10000000-0000-4000-8000-000000000001','95050000-0000-4000-8000-000000000001','95040000-0000-4000-8000-000000000001','Practice','practice','Observed school action',1);
insert into app.activity_completions(school_id,id,activity_id,learner_id)values('10000000-0000-4000-8000-000000000001','95060000-0000-4000-8000-000000000001','95050000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012');
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,completed_at)values('10000000-0000-4000-8000-000000000001','95070000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','activity.complete','activity','95060000-0000-4000-8000-000000000001',1,'{}','recognition-source-golden','COMPLETED',clock_timestamp());
insert into internal.processed_events(event_id,school_id,source_type,source_id)values('95070000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','COMPLETION','95060000-0000-4000-8000-000000000001');
insert into app.habit_observations(school_id,id,learner_id,kind,source_type,source_object_id,occurred_at,source_event_id)select'10000000-0000-4000-8000-000000000001','95080000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','practice','ACTIVITY_COMPLETION','95060000-0000-4000-8000-000000000001',completed_at,'95070000-0000-4000-8000-000000000001'from app.activity_completions where id='95060000-0000-4000-8000-000000000001';
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,lease_token,lease_until)values('10000000-0000-4000-8000-000000000001','95090000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','habit.observed','observation','95080000-0000-4000-8000-000000000001',1,'{}','recognition-habit-golden','PROCESSING','95100000-0000-4000-8000-000000000001',clock_timestamp()+interval'30 seconds');
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,lease_token,lease_until)values('10000000-0000-4000-8000-000000000001','95090000-0000-4000-8000-000000000099','20000000-0000-4000-8000-000000000013','habit.observed','observation','95080000-0000-4000-8000-000000000001',1,'{}','recognition-forged-actor','PROCESSING','95100000-0000-4000-8000-000000000099',clock_timestamp()+interval'30 seconds');
set local role cuevo_worker;
select throws_ok($$select internal.process_recognition_event('95090000-0000-4000-8000-000000000099','95100000-0000-4000-8000-000000000099')$$,'22023',null,'wrong actor cannot replay another learner observation for XP');
select lives_ok($$select internal.process_recognition_event('95090000-0000-4000-8000-000000000001','95100000-0000-4000-8000-000000000001')$$,'worker awards only validated habit event before atomic ack');
reset role;
select is((select count(*)from app.xp_ledger where observation_id='95080000-0000-4000-8000-000000000001'),1::bigint,'one observed action awards one period ledger row');
select is((select points from app.xp_ledger where observation_id='95080000-0000-4000-8000-000000000001'),5,'configured school points preserved');
select is((select count(*)from app.learner_achievements where learner_id='20000000-0000-4000-8000-000000000012'and period_id=(select period_id from portfolio_test_ids)),1::bigint,'verified points earn versioned milestone');
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,lease_token,lease_until)values('10000000-0000-4000-8000-000000000001','95090000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000012','habit.observed','observation','95080000-0000-4000-8000-000000000001',1,'{}','recognition-habit-duplicate','PROCESSING','95100000-0000-4000-8000-000000000002',clock_timestamp()+interval'30 seconds');
set local role cuevo_worker;select lives_ok($$select internal.process_recognition_event('95090000-0000-4000-8000-000000000002','95100000-0000-4000-8000-000000000002')$$,'duplicate event same observation acknowledges without duplicate XP');reset role;
select is((select count(*)from app.xp_ledger where observation_id='95080000-0000-4000-8000-000000000001'),1::bigint,'source dedup prevents award replay');
insert into app.enrollments(school_id,class_id,student_actor_id,effective_from)values('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000012','2026-09-01')on conflict(school_id,class_id,student_actor_id)do update set status='active';
insert into app.recognition_periods(school_id,id,class_id,policy_id,title,starts_at,ends_at,approved_by)select'10000000-0000-4000-8000-000000000001','95110000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002',policy_id,'Other class',clock_timestamp()-interval'1 hour',clock_timestamp()+interval'1 hour','20000000-0000-4000-8000-000000000001'from portfolio_test_ids;
select is(internal.award_recognition_observation('10000000-0000-4000-8000-000000000001','95080000-0000-4000-8000-000000000001','95110000-0000-4000-8000-000000000001'),0,'multi-class learner cannot transfer an observation to another class period');
select is((select count(*)from app.xp_ledger where period_id='95110000-0000-4000-8000-000000000001'),0::bigint,'wrong class period stores no XP');
reset role;select ok(not exists(select 1 from pg_class table_row join pg_namespace n on n.oid=table_row.relnamespace join pg_roles r on r.rolname in('anon','authenticated','service_role','cuevo_api','cuevo_worker')where n.nspname='app'and table_row.relname in('portfolio_items','portfolio_revisions','portfolio_reviews','portfolio_current','xp_ledger','recognition_policies','learner_achievements','leaderboard_participation')and has_table_privilege(r.oid,table_row.oid,'SELECT,INSERT,UPDATE,DELETE')),'portfolio recognition tables have no raw runtime or Data API grants');
select*from finish();rollback;
